boolean validateWrite(boolean checkCircularity)
{
    KCS_KAOItemStateTable   itemStateTable;
    NDXItemStateTable       ndxItemStateTable;

    boolean ret = next validateWrite(checkCircularity);
    if (ret)
    {
        itemStateTable = KCS_KAOItemStateTable::find(this.inventTable().KCS_KAOItemState);
        if (itemStateTable.ProdBlock)
        {
            select firstonly ndxItemStateTable where ndxItemStateTable.RefRecId_KCS_KAO_ItemStateTable == itemStateTable.RecId;
            ret = checkFailed(strFmt("@NDX:NXANotAllowedNewBOMLine", ndxItemStateTable.InfoItemState));
        }
    }
    return ret;
}

