/// <summary>
/// N.Freidenberger 02.07.2025
/// </summary>
/// <param name = "_parentItemId">_parentItemId</param>
/// <param name = "_parentConfigId">_parentConfigId</param>
/// <param name = "_itemRouteId">_itemRouteId</param>
/// <param name = "_siteId">_siteId</param>
/// <returns>VendAccount</returns>
public VendAccount vendId(
    ItemId                      _parentItemId,
    EcoResItemConfigurationName _parentConfigId,
    ItemRouteId                 _itemRouteId,
    InventSiteId                _siteId
    )
{

    VendAccount   vendId  = next vendId(_parentItemId,_parentConfigId,_itemRouteId,_siteId);
    Route       route = this.route(_itemRouteId);
    RouteOpr    routeOpr;

    if (route)
        routeOpr = route.routeOpr(_parentItemId,_parentConfigId,_siteId, null);

    if (routeOpr.RecId)
    {
        vendId = routeOpr.RouteOprMap::wrkCtrVendId();
    }

    if (! vendId)
    {
        vendId = this.VendId;
    }

    if (! vendId)
    {
        InventTable inventTable = this.inventTable();
        vendId      = inventTable.KCS_HK2Vendor != '' ? InventTable.KCS_HK2Vendor : inventTable.primaryVendorId(this.InventDimId);
    }

    return vendId;
}
